{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01", "C12", "C20", "C21", "C31", "C41", "C56", "C64", "C66"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01", "C12", "C20", "C21", "C56", "C64", "C66"],
  "claims": [
    {
      "claim": "Cibenzoline, a 2-imidazoline-containing drug, has human absolute oral bioavailability values of 0.92, 0.874 ± 0.095, and ~85%, with L2 records reporting F=0.85 and complete bioavailability of solid forms relative to oral solution; L4 additionally reports a 92% fraction absorbed, showing the 2-imidazoline scaffold supports both high absorption and F well above 20%.",
      "card_ids": ["C01", "C12", "C20", "C31", "C41", "C56"]
    },
    {
      "claim": "Clonidine, which shares the 2-imidazoline-aryl amine motif with the query, has a human fraction absorbed of 0.95/95%, providing direct absorption evidence that this motif is compatible with high intestinal absorption.",
      "card_ids": ["C64", "C66"]
    },
    {
      "claim": "Midaglizole, another 2-imidazoline-containing drug, has systemic bioavailability of at least 75% in humans based on urinary recovery of unchanged drug, further supporting F ≥ 20% for the query scaffold.",
      "card_ids": ["C21"]
    },
    {
      "claim": "The remaining L4 records (felodipine, dasatinib, chloroquine, clopidogrel, losartan, oxymetazoline, hydralazine) are not structurally transferable to the query; hydralazine's high absorption with extensive first-pass metabolism is not applicable because the query lacks the hydrazine moiety and has no analogous metabolic liability.",
      "card_ids": ["C60", "C62", "C65", "C61", "C59", "C58", "C63"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "L4 intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C56", "C64", "C66"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "No IV-versus-oral AUC comparison or absolute F value is available for the query.",
    "No query-specific first-pass metabolism or clearance data are available; hydralazine's first-pass caution is not transferable because the query lacks hydrazine.",
    "L4 records are for reference molecules, not the query; transfer from clonidine and cibenzoline relies on the shared 2-imidazoline motif and is not exact-structure evidence."
  ],
  "decision_summary": "Predicted high maintained and strengthened: L4 adds human fraction-absorbed evidence for clonidine (95%) and cibenzoline (92%), both 2-imidazoline-containing drugs, supporting high intestinal absorption for the query scaffold; combined with prior human absolute F records for cibenzoline (~0.85–0.92) and midaglizole (≥75%), F ≥ 20% is well supported. No transferable affirmative evidence indicates F < 20%."
}

